import {productionOptions,owns,surface} from './world.js';
import {CONTENT_DATA} from './content-data.js';
const factories=new Set(['goldmine','lumber','supply','metal']);
export const isFactory=type=>factories.has(type);
export function productionQuote(s,b,index){const option=productionOptions[index],source=CONTENT_DATA.buildings[b?.type]?.[0];if(!b||!option||!factories.has(b.type)||!source)return{ok:false,message:'Elige una fábrica y un ciclo válido.'};const speed=s.difficulty==='easy'?10:s.difficulty==='hard'?3:1,amount=Math.max(1,Math.floor(source.collect*option.multiplier*(1+(b.level-1)*.4)));return{ok:true,index,minutes:option.minutes,multiplier:option.multiplier,duration:option.minutes*60/speed,amount,speed};}
export function createIndustry({BUILDINGS,storageCap,builders,usedBuilders,log}){
 const result=(ok,message)=>({ok,message}),canPay=(s,cost)=>Object.entries(cost).every(([k,v])=>s.resources[k]>=v),pay=(s,cost)=>{for(const[k,v]of Object.entries(cost))s.resources[k]-=v;};
 function startProduction(s,id,index){const b=s.buildings.find(b=>b.id===id),q=productionQuote(s,b,index);if(!q.ok)return q;if(s.battle||b.hp<=0||b.job)return result(false,'La fábrica debe estar operativa.');if(b.production?.status==='working')return result(false,'Espera a que termine el ciclo actual.');if(b.stored>=1)return result(false,'Recoge primero la producción que queda almacenada.');b.productionMode='cycles';b.production={index,started:s.time,ends:s.time+q.duration,amount:q.amount,status:'working'};return result(true,'Producción encargada: '+q.amount+' materiales en '+Math.ceil(q.duration)+' segundos.');}
 function tickProduction(s,b){const p=b.production;if(p?.status==='working'&&s.time>=p.ends){b.stored+=p.amount;p.status='ready';log(s,BUILDINGS[b.type].name+': lote listo para recoger.');}}
 function bridgeQuote(s,x,y,existingId=null){let message='';const bridge=s.world?.bridges.find(b=>b.id===existingId),cost=existingId?{gold:200,wood:200,metal:100}:{gold:300,wood:350,metal:180};if(bridge){x=bridge.x;y=bridge.y;}
  if(!s.world)message='El archipiélago no está disponible.';else if(s.battle)message='Termina la batalla antes de construir.';else if(usedBuilders(s)>=builders(s))message='Necesitas una cuadrilla libre.';else if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x+5>100||y+5>100)message='Marca un paso dentro del mapa.';else if(!existingId&&s.world.bridges.length>=30)message='Alcanzaste el límite de puentes.';else if(existingId&&(!bridge||!bridge.broken||bridge.job))message='Este puente no necesita reparación.';
  const anchors=[[[x+2,y-1],[x+2,y+5]],[[x-1,y+2],[x+5,y+2]]];let orientation=bridge?.orientation??0;
  if(!message){const direction=anchors.findIndex(pair=>pair.every(([x,y])=>surface(s,x,y)==='grass')&&pair.some(([x,y])=>owns(s,x,y)));if(direction<0)message='El puente debe unir dos orillas y partir de tu territorio.';else orientation=direction;}
  if(!message&&!existingId){let water=0;for(let yy=y;yy<y+5;yy++)for(let xx=x;xx<x+5;xx++)if(surface(s,xx,yy)==='water')water++;if(!water)message='Este solar no cruza agua.';if(s.world.bridges.some(b=>x<b.x+5&&x+5>b.x&&y<b.y+5&&y+5>b.y)||s.buildings.some(b=>x<b.x+BUILDINGS[b.type].size&&x+5>b.x&&y<b.y+BUILDINGS[b.type].size&&y+5>b.y))message='El paso se superpone a otra construcción.';}
  if(!message&&!canPay(s,cost))message='Faltan materiales para el puente.';return{ok:!message,message,cost,x,y,orientation,existingId,duration:60};
 }
 function buildBridge(s,x,y,existingId=null){const q=bridgeQuote(s,x,y,existingId);if(!q.ok)return q;pay(s,q.cost);const bridge=existingId?s.world.bridges.find(b=>b.id===existingId):{id:'br'+s.serial++,x,y,orientation:q.orientation,broken:true,fixed:false};bridge.job={started:s.time,ends:s.time+q.duration};if(!existingId){s.world.bridges.push(bridge);s.stats.built++;}s.world.revision++;return result(true,existingId?'Reparación del puente iniciada.':'Puente en construcción. El paso se abrirá al terminar.');}
 function tickBridges(s){for(const b of s.world?.bridges||[])if(b.job&&b.job.ends<=s.time){b.job=null;b.broken=false;s.world.revision++;s.xp+=80;log(s,'Puente operativo: nueva ruta terrestre disponible.');}}
 function trade(s,resource,amount,direction){if(!['wood','supply','metal'].includes(resource)||![100,200,300].includes(amount)||!['buy','sell'].includes(direction))return result(false,'Intercambio no válido.');if(s.battle||!s.buildings.some(b=>b.type==='market'&&b.hp>0&&!b.job))return result(false,'Necesitas un mercado operativo.');const market=s.world?.market;if(!s.world)return result(false,'El comercio requiere el archipiélago.');const m=market&&s.time-market.started<72000?market:{started:s.time,used:0};if(m.used>=20)return result(false,'El mercado ha agotado sus 20 operaciones de este período.');const gold=Math.ceil(amount*(resource==='metal'?1.5:1)*(direction==='sell'?.75:1));if(direction==='buy'){if(s.resources.gold<gold)return result(false,'No tienes suficiente oro.');if(s.resources[resource]+amount>storageCap(s))return result(false,'Amplía los silos antes de comprar este lote.');s.resources.gold-=gold;s.resources[resource]+=amount;}else{if(s.resources[resource]<amount)return result(false,'No tienes suficientes materiales.');if(s.resources.gold+gold>storageCap(s))return result(false,'El almacén de oro está lleno.');s.resources[resource]-=amount;s.resources.gold+=gold;}m.used++;s.world.market=m;return result(true,direction==='buy'?'Lote comprado y recibido.':'Material vendido por '+gold+' de oro.');}
 return{startProduction,tickProduction,bridgeQuote,buildBridge,tickBridges,trade};
}
